findings.codeql_raw_query:
/**
 * @name SQL injection via text() or raw SQL execution
 * @description User input flowing into raw SQL text() constructs or execute() calls can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for text() function calls in SQLAlchemy
    sink = API::moduleImport("sqlalchemy").getMember("text").getACall().getArg(0) or
    // Look for execute() calls with raw SQL
    sink = API::moduleImport("sqlalchemy").getMember("engine").getMember("Engine").getMember("execute").getACall().getArg(0) or
    // Look for connection.execute() calls
    sink = API::moduleImport("sqlalchemy").getMember("engine").getMember("Connection").getMember("execute").getACall().getArg(0) or
    // Look for raw SQL in select() or other query constructs
    sink = API::moduleImport("sqlalchemy").getMember("sql").getMember("text").getACall().getArg(0)
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@ flowing into raw SQL text.", source.getNode(), "user input"
